WITH sales_combined AS ( SELECT cs.cs_sold_date_sk AS sold_date_sk, cs.cs_net_paid_inc_tax AS net_paid, cs.cs_net_profit AS net_profit, p.p_promo_id AS promo_id FROM catalog_sales cs JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk UNION ALL SELECT ss.ss_sold_date_sk AS sold_date_sk, ss.ss_net_paid_inc_tax AS net_paid, ss.ss_net_profit AS net_profit, p.p_promo_id AS promo_id FROM store_sales ss JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk ), daily_agg AS ( SELECT sold_date_sk, SUM(net_paid) AS total_net_paid, SUM(net_profit) AS total_net_profit, COUNT(DISTINCT promo_id) AS distinct_promos_active FROM sales_combined GROUP BY sold_date_sk ) SELECT sold_date_sk, total_net_paid, total_net_profit, distinct_promos_active, AVG(total_net_profit) OVER (ORDER BY sold_date_sk ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS moving_avg_profit_3, CASE WHEN total_net_profit > 100000 THEN 'High' WHEN total_net_profit > 50000 THEN 'Medium' ELSE 'Low' END AS profit_flag FROM daily_agg ORDER BY sold_date_sk
